@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground;
  }
}

/* Responsive Design Improvements */
@layer base {
  /* Improved scrollbar styling */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }

  ::-webkit-scrollbar-track {
    background: hsl(var(--background));
  }

  ::-webkit-scrollbar-thumb {
    background: hsl(var(--border));
    border-radius: 4px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: hsl(var(--muted-foreground));
  }

  /* Improved focus styles for accessibility */
  *:focus-visible {
    outline: 2px solid hsl(var(--ring));
    outline-offset: 2px;
  }

  /* Better text selection */
  ::selection {
    background: hsl(var(--primary) / 0.2);
    color: hsl(var(--primary-foreground));
  }
}

/* Custom utility classes */
@layer utilities {
  .bg-gradient-primary {
    background: var(--gradient-primary);
  }

  /* UPI Payment Button Animations */
  .upi-payment-button {
    @apply relative overflow-hidden;
    background: linear-gradient(135deg, #22c55e, #16a34a);
    animation: pulse-glow 2s ease-in-out infinite;
    box-shadow: 0 0 20px rgba(34, 197, 94, 0.4);
    transform: translateY(0);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .upi-payment-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 5px 30px rgba(34, 197, 94, 0.6);
    animation: none;
  }

  .upi-payment-button::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);
    animation: shimmer 3s ease-in-out infinite;
  }

  @keyframes pulse-glow {
    0%, 100% {
      box-shadow: 0 0 20px rgba(34, 197, 94, 0.4);
      background: linear-gradient(135deg, #22c55e, #16a34a);
    }
    50% {
      box-shadow: 0 0 30px rgba(34, 197, 94, 0.7);
      background: linear-gradient(135deg, #16a34a, #22c55e);
    }
  }

  @keyframes shimmer {
    0% {
      left: -100%;
    }
    100% {
      left: 100%;
    }
  }

  /* Attention grabbing bounce */
  .upi-attention {
    animation: attention-bounce 1s ease-in-out infinite;
  }

  @keyframes attention-bounce {
    0%, 20%, 50%, 80%, 100% {
      transform: translateY(0);
    }
    40% {
      transform: translateY(-5px);
    }
    60% {
      transform: translateY(-3px);
    }
  }

  .bg-gradient-card {
    background: var(--gradient-card);
  }

  .bg-gradient-hero {
    background: var(--gradient-hero);
  }

  .shadow-glow {
    box-shadow: var(--shadow-glow);
  }

  .shadow-card {
    box-shadow: var(--shadow-card);
  }

  .transition-smooth {
    transition: var(--transition-smooth);
  }
}

/* Animations */
@layer utilities {
  .animate-fade-in {
    animation: fadeIn 1s ease-out;
  }

  .animate-slide-up {
    animation: slideUp 0.8s ease-out;
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(20px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes slideUp {
    from {
      opacity: 0;
      transform: translateY(30px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

/* Responsive Design & Mobile Improvements */
@layer utilities {
  /* Loading Animations */
  .loading-spinner {
    @apply animate-spin rounded-full border-2 border-current border-t-transparent;
  }

  .loading-pulse {
    @apply animate-pulse bg-gradient-to-r from-muted via-muted-foreground/10 to-muted rounded;
  }

  .loading-skeleton {
    @apply loading-pulse h-4 w-full mb-2;
  }

  /* Better Button States */
  .btn-loading {
    @apply relative text-transparent cursor-not-allowed;
  }

  .btn-loading::after {
    content: '';
    @apply absolute inset-0 m-auto w-4 h-4 loading-spinner border-current;
  }

  /* Responsive Table Improvements */
  .table-responsive {
    @apply w-full overflow-x-auto;
  }

  .table-mobile {
    @apply block md:table;
  }

  .table-mobile thead {
    @apply hidden md:table-header-group;
  }

  .table-mobile tbody {
    @apply block md:table-row-group;
  }

  .table-mobile tr {
    @apply block border border-border rounded-lg mb-4 p-4 md:table-row md:border-0 md:rounded-none md:mb-0 md:p-0;
  }

  .table-mobile td {
    @apply block text-right border-0 py-2 md:table-cell md:text-left md:border-b md:py-4;
  }

  .table-mobile td::before {
    content: attr(data-label) ': ';
    @apply font-semibold text-left float-left md:hidden;
  }

  /* Modal & Dialog Improvements */
  .modal-overlay {
    @apply fixed inset-0 z-50 bg-black/50 backdrop-blur-sm;
    animation: fadeIn 0.2s ease-out;
  }

  .modal-content {
    @apply fixed left-1/2 top-1/2 z-50 w-full max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-lg bg-background p-6 shadow-lg;
    animation: modalSlideIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  @keyframes modalSlideIn {
    from {
      opacity: 0;
      transform: translate(-50%, -60%) scale(0.95);
    }
    to {
      opacity: 1;
      transform: translate(-50%, -50%) scale(1);
    }
  }

  /* Mobile Navigation Improvements */
  .mobile-nav {
    @apply fixed inset-x-0 top-0 z-40 bg-background/95 backdrop-blur-md border-b;
  }

  .mobile-nav-menu {
    @apply fixed inset-y-0 left-0 z-50 w-64 bg-background border-r transform transition-transform duration-300 ease-in-out;
  }

  .mobile-nav-menu.closed {
    @apply -translate-x-full;
  }

  .mobile-nav-menu.open {
    @apply translate-x-0;
  }

  /* Form Improvements */
  .form-group {
    @apply space-y-2;
  }

  .form-input {
    @apply w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background;
    @apply placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2;
    @apply disabled:cursor-not-allowed disabled:opacity-50;
  }

  .form-label {
    @apply text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70;
  }

  .form-error {
    @apply text-sm text-destructive;
  }

  /* Card Improvements */
  .card-hover {
    @apply transition-all duration-200 hover:shadow-lg hover:-translate-y-1;
  }

  .card-interactive {
    @apply card-hover cursor-pointer border-2 border-transparent hover:border-primary/20;
  }

  /* Better Status Indicators */
  .status-indicator {
    @apply inline-flex items-center rounded-full px-2 py-1 text-xs font-medium;
  }

  .status-success {
    @apply bg-green-100 text-green-800 dark:bg-green-900/20 dark:text-green-400;
  }

  .status-warning {
    @apply bg-yellow-100 text-yellow-800 dark:bg-yellow-900/20 dark:text-yellow-400;
  }

  .status-error {
    @apply bg-red-100 text-red-800 dark:bg-red-900/20 dark:text-red-400;
  }

  .status-info {
    @apply bg-blue-100 text-blue-800 dark:bg-blue-900/20 dark:text-blue-400;
  }
}

/* Mobile-First Responsive Design */
@layer utilities {
  /* Hide elements on mobile */
  .mobile-hidden {
    @apply hidden md:block;
  }

  /* Show only on mobile */
  .mobile-only {
    @apply block md:hidden;
  }

  /* Responsive text sizes */
  .text-responsive-xs {
    @apply text-xs sm:text-sm;
  }

  .text-responsive-sm {
    @apply text-sm sm:text-base;
  }

  .text-responsive-base {
    @apply text-base sm:text-lg;
  }

  .text-responsive-lg {
    @apply text-lg sm:text-xl;
  }

  .text-responsive-xl {
    @apply text-xl sm:text-2xl;
  }

  /* Responsive spacing */
  .spacing-responsive {
    @apply p-4 sm:p-6 md:p-8;
  }

  .gap-responsive {
    @apply gap-2 sm:gap-4 md:gap-6;
  }

  /* Grid responsiveness */
  .grid-responsive {
    @apply grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4;
  }

  .grid-responsive-cards {
    @apply grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 md:gap-6;
  }
}

/* Print Styles */
@media print {
  .no-print {
    @apply hidden;
  }

  .print-only {
    @apply block;
  }

  body {
    @apply text-black bg-white;
  }

  .card {
    @apply border border-black shadow-none;
  }
}

server/middleware/authMiddleware.ts.content:
import { Request, Response, NextFunction } from 'express';
import { authService } from '../services/authService';
import { PERMISSIONS } from '@shared/schema';

// Extend Express Request type to include user
declare global {
  namespace Express {
    interface Request {
      user?: any;
    }
  }
}

// Authentication middleware - verify session token
export const authenticate = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const token = req.headers.authorization?.replace('Bearer ', '') || 
                  req.cookies?.admin_token;

    if (!token) {
      return res.status(401).json({ 
        message: 'Access denied. No authentication token provided.',
        code: 'NO_TOKEN' 
      });
    }

    const user = await authService.verifySession(token);
    if (!user) {
      return res.status(401).json({ 
        message: 'Access denied. Invalid or expired token.',
        code: 'INVALID_TOKEN' 
      });
    }

    req.user = user;
    next();
  } catch (error) {
    console.error('Authentication error:', error);
    res.status(500).json({ message: 'Authentication failed' });
  }
};

// Permission-based authorization middleware
export const requirePermission = (permission: string) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ 
        message: 'Authentication required',
        code: 'NOT_AUTHENTICATED' 
      });
    }

    if (!authService.hasPermission(req.user, permission)) {
      return res.status(403).json({ 
        message: `Access denied. Required permission: ${permission}`,
        code: 'INSUFFICIENT_PERMISSIONS',
        required: permission,
        userRole: req.user.role
      });
    }

    next();
  };
};

// Role-based authorization middleware
export const requireRole = (roles: string | string[]) => {
  const roleArray = Array.isArray(roles) ? roles : [roles];

  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ 
        message: 'Authentication required',
        code: 'NOT_AUTHENTICATED' 
      });
    }

    if (!roleArray.includes(req.user.role)) {
      return res.status(403).json({ 
        message: `Access denied. Required role: ${roleArray.join(' or ')}`,
        code: 'INSUFFICIENT_ROLE',
        required: roleArray,
        userRole: req.user.role
      });
    }

    next();
  };
};

// Multiple permissions (user needs ALL of them)
export const requireAllPermissions = (permissions: string[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ 
        message: 'Authentication required',
        code: 'NOT_AUTHENTICATED' 
      });
    }

    if (!authService.hasAllPermissions(req.user, permissions)) {
      return res.status(403).json({ 
        message: `Access denied. Required permissions: ${permissions.join(', ')}`,
        code: 'INSUFFICIENT_PERMISSIONS',
        required: permissions,
        userRole: req.user.role
      });
    }

    next();
  };
};

// Any permission (user needs at least ONE of them)
export const requireAnyPermission = (permissions: string[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ 
        message: 'Authentication required',
        code: 'NOT_AUTHENTICATED' 
      });
    }

    if (!authService.hasAnyPermission(req.user, permissions)) {
      return res.status(403).json({ 
        message: `Access denied. Required at least one of: ${permissions.join(', ')}`,
        code: 'INSUFFICIENT_PERMISSIONS',
        required: permissions,
        userRole: req.user.role
      });
    }

    next();
  };
};

