import { google } from 'googleapis';
import type { Booking } from '@shared/schema';

export class GoogleSheetsService {
  private sheets: any;
  private spreadsheetId: string;

  constructor() {
    // Initialize Google Sheets API with credentials from environment
    const credentials = JSON.parse(process.env.GOOGLE_SHEETS_CREDENTIALS || '{}');

    const auth = new google.auth.GoogleAuth({
      credentials,
      scopes: ['https://www.googleapis.com/auth/spreadsheets'],
    });

    this.sheets = google.sheets({ version: 'v4', auth });
    this.spreadsheetId = process.env.GOOGLE_SHEETS_ID || '';
  }

  async addBookingToSheet(booking: Booking) {
    try {
      // Check if Google Sheets API is available
      if (!this.spreadsheetId) {
        console.log('Google Sheets not configured, skipping...');
        return null;
      }

      // Create header row if sheet is empty
      await this.ensureHeaderRow();

      const values = [
        [
          new Date().toISOString(),
          booking.id,
          booking.name,
          booking.email,
          booking.phone,
          booking.gender || '',
          booking.ticketCount,
          booking.ticketType || 'early_bird',
          Array.isArray(booking.guests) ? booking.guests.join(', ') : booking.guests || '',
          Array.isArray(booking.guestGenders) ? booking.guestGenders.join(', ') : booking.guestGenders || '',
          booking.couponCode || '',
          booking.couponDiscount || 0,
          booking.totalAmount,
          booking.paymentStatus,
          Array.isArray(booking.guestCodes) ? booking.guestCodes.join(', ') : booking.guestCodes || '',
          Array.isArray(booking.scannedGuests) ? booking.scannedGuests.join(', ') : booking.scannedGuests || '',
          Array.isArray(booking.scannedGuests) ? booking.scannedGuests.length : 0,
          booking.paymentScreenshot ? 
            (booking.paymentScreenshot.startsWith('http') ? 
              booking.paymentScreenshot : 
              `https://events.qlora.in${booking.paymentScreenshot}`) : ''
        ]
      ];

      const request = {
        spreadsheetId: this.spreadsheetId,
        range: 'Sheet1!A:S',
        valueInputOption: 'USER_ENTERED',
        resource: {
          values,
        },
      };

      const response = await this.sheets.spreadsheets.values.append(request);
      console.log('Successfully added booking to Google Sheets');
      return response.data;
    } catch (error: any) {
      if (error.message && error.message.includes('Google Sheets API has not been used')) {
        console.log('⚠️  Google Sheets API is not enabled. Please enable it in Google Cloud Console at:');
        console.log('https://console.developers.google.com/apis/api/sheets.googleapis.com/overview');
        // Don't throw error, just log it so booking still works
        return null;
      }
      console.error('Error adding to Google Sheets:', error);
      // Don't throw error to prevent booking failure
      return null;
    }
  }

  // Method to sync existing bookings - updates or adds as needed
  async syncBookingToSheet(booking: Booking) {
    try {
      return await this.addBookingToSheet(booking);
    } catch (error: any) {
      console.error('Error syncing booking to Google Sheets:', error);
      throw error;
    }
  }

  async updateBookingStatus(bookingId: number, status: string) {
    try {
      if (!this.spreadsheetId) {
        console.log('Google Sheets not configured, skipping update...');
        return null;
      }

      // This would require finding the booking row and updating it
      // For now, just log the action
      console.log(`Would update booking ${bookingId} status to ${status} in Google Sheets`);
      return null;
    } catch (error) {
      console.error('Error updating booking status in Google Sheets:', error);
      return null;
    }
  }

  async ensureHeaderRow() {
    try {
      // Check if there are any values in the sheet
      const getResponse = await this.sheets.spreadsheets.values.get({
        spreadsheetId: this.spreadsheetId,
        range: 'Sheet1!A1:S1',
      });

      if (!getResponse.data.values || getResponse.data.values.length === 0) {
        // Add header row
        const headerValues = [
          [
            'Timestamp',
            'Booking ID',
            'Name',
            'Email',
            'Phone',
            'Gender',
            'Ticket Count',
            'Ticket Type',
            'Guests',
            'Guest Genders',
            'Coupon Code',
            'Coupon Discount',
            'Total Amount',
            'Payment Status',
            'Guest Codes',
            'Scanned Guests',
            'Entry Count',
            'Payment Screenshot'
          ]
        ];

        await this.sheets.spreadsheets.values.update({
          spreadsheetId: this.spreadsheetId,
          range: 'Sheet1!A1:S1',
          valueInputOption: 'USER_ENTERED',
          resource: {
            values: headerValues,
          },
        });
      }
    } catch (error) {
      console.error('Error creating header row:', error);
    }
  }



  async addPaymentScreenshotToSheet(bookingId: number, screenshotUrl: string) {
    try {
      if (!this.spreadsheetId) {
        console.log('Google Sheets not configured for screenshot upload');
        return null;
      }

      // Find the row with this booking ID
      const getResponse = await this.sheets.spreadsheets.values.get({
        spreadsheetId: this.spreadsheetId,
        range: 'Sheet1!A:S',
      });

      const rows = getResponse.data.values || [];
      const rowIndex = rows.findIndex((row: any) => row[1] === bookingId.toString());

      if (rowIndex !== -1) {
        const range = `Sheet1!S${rowIndex + 1}`;  // Column S for screenshot URL
        await this.sheets.spreadsheets.values.update({
          spreadsheetId: this.spreadsheetId,
          range,
          valueInputOption: 'USER_ENTERED',
          resource: {
            values: [[screenshotUrl]],
          },
        });
        console.log(`✅ Added payment screenshot URL to Google Sheets: ${screenshotUrl}`);
        return true;
      } else {
        console.log(`⚠️ Booking ${bookingId} not found in Google Sheets for screenshot update`);
        return false;
      }
    } catch (error: any) {
      console.error('Error adding screenshot to Google Sheets:', error);
      if (error.message?.includes('API has not been used')) {
        console.log('Please enable Google Sheets API at: https://console.developers.google.com/apis/api/sheets.googleapis.com/overview?project=640169928600');
      }
      return false;
    }
  }

  async testConnection() {
    try {
      if (!this.spreadsheetId) {
        return { success: false, message: 'No spreadsheet ID configured' };
      }

      const response = await this.sheets.spreadsheets.get({
        spreadsheetId: this.spreadsheetId,
      });

      return { 
        success: true, 
        message: 'Google Sheets API is working',
        title: response.data.properties?.title 
      };
    } catch (error: any) {
      console.error('Google Sheets test failed:', error);
      if (error.message?.includes('API has not been used')) {
        return { 
          success: false, 
          message: 'Google Sheets API needs to be enabled. Visit: https://console.developers.google.com/apis/api/sheets.googleapis.com/overview?project=640169928600'
        };
      }
      return { success: false, message: error?.message || 'Unknown error' };
    }
  }

  async resetSheet() {
    try {
      if (!this.spreadsheetId) {
        console.log('Google Sheets not configured, cannot reset');
        return { success: false, message: 'No spreadsheet ID configured' };
      }

      console.log('🔄 Resetting Google Sheet and starting fresh...');

      // Clear all existing data in the sheet
      await this.sheets.spreadsheets.values.clear({
        spreadsheetId: this.spreadsheetId,
        range: 'Sheet1!A:Z', // Clear all columns
      });

      // Add fresh header row
      const headerValues = [
        [
          'Timestamp',
          'Booking ID',
          'Name',
          'Email',
          'Phone',
          'Gender',
          'Ticket Count',
          'Ticket Type',
          'Guests',
          'Guest Genders',
          'Coupon Code',
          'Coupon Discount',
          'Total Amount',
          'Payment Status',
          'Guest Codes',
          'Scanned Guests',
          'Entry Count',
          'Payment Screenshot'
        ]
      ];

      await this.sheets.spreadsheets.values.update({
        spreadsheetId: this.spreadsheetId,
        range: 'Sheet1!A1:R1',
        valueInputOption: 'USER_ENTERED',
        resource: {
          values: headerValues,
        },
      });

      console.log('✅ Google Sheet reset successfully with fresh headers');
      return { success: true, message: 'Google Sheet reset successfully' };

    } catch (error: any) {
      console.error('❌ Error resetting Google Sheet:', error);
      if (error.message?.includes('API has not been used')) {
        return { 
          success: false, 
          message: 'Google Sheets API needs to be enabled. Visit: https://console.developers.google.com/apis/api/sheets.googleapis.com/overview'
        };
      }
      return { success: false, message: error?.message || 'Unknown error' };
    }
  }

  async syncAllBookingsToFreshSheet(bookings: any[]) {
    try {
      if (!this.spreadsheetId) {
        console.log('Google Sheets not configured, cannot sync');
        return { success: false, message: 'No spreadsheet ID configured' };
      }

      console.log(`🔄 Syncing ${bookings.length} bookings to fresh Google Sheet...`);

      let successCount = 0;
      let errorCount = 0;

      for (const booking of bookings) {
        try {
          await this.addBookingToSheet(booking);
          successCount++;
          console.log(`✅ Synced booking ${booking.id}: ${booking.name}`);
        } catch (error) {
          errorCount++;
          console.error(`❌ Failed to sync booking ${booking.id}:`, error);
        }
      }

      console.log(`🎉 Sync completed: ${successCount} success, ${errorCount} errors`);
      return { 
        success: true, 
        message: `Synced ${successCount} bookings successfully`, 
        successCount, 
        errorCount 
      };

    } catch (error: any) {
      console.error('❌ Error during bulk sync:', error);
      return { success: false, message: error?.message || 'Bulk sync failed' };
    }
  }

  async updateBookingPaymentStatus(bookingId: number, status: string) {
    try {
      if (!this.spreadsheetId) {
        console.log('Google Sheets not configured for status update');
        return null;
      }

      // Find the row with this booking ID
      const getResponse = await this.sheets.spreadsheets.values.get({
        spreadsheetId: this.spreadsheetId,
        range: 'Sheet1!A:M',
      });

      const rows = getResponse.data.values || [];
      const rowIndex = rows.findIndex((row: any) => row[1] === bookingId.toString());

      if (rowIndex !== -1) {
        const range = `Sheet1!K${rowIndex + 1}`;  // Column K for payment status
        await this.sheets.spreadsheets.values.update({
          spreadsheetId: this.spreadsheetId,
          range,
          valueInputOption: 'USER_ENTERED',
          resource: {
            values: [[status]],
          },
        });
        console.log(`✅ Updated booking ${bookingId} status to ${status} in Google Sheets`);
        return true;
      } else {
        console.log(`⚠️ Booking ${bookingId} not found in Google Sheets for status update`);
        return false;
      }
    } catch (error) {
      console.error('Error updating booking status in Google Sheets:', error);
      return null;
    }
  }

  async deleteBookingFromSheet(bookingId: number) {
    try {
      if (!this.spreadsheetId) {
        console.log('Google Sheets not configured for booking deletion');
        return null;
      }

      // Find the row with this booking ID
      const getResponse = await this.sheets.spreadsheets.values.get({
        spreadsheetId: this.spreadsheetId,
        range: 'Sheet1!A:M',
      });

      const rows = getResponse.data.values || [];
      const rowIndex = rows.findIndex((row: any) => row[1] === bookingId.toString());

      if (rowIndex !== -1) {
        // Delete the row by clearing its contents and shifting rows up
        await this.sheets.spreadsheets.batchUpdate({
          spreadsheetId: this.spreadsheetId,
          resource: {
            requests: [{
              deleteDimension: {
                range: {
                  sheetId: 0, // First sheet
                  dimension: 'ROWS',
                  startIndex: rowIndex,
                  endIndex: rowIndex + 1
                }
              }
            }]
          }
        });
        console.log(`✅ Deleted booking ${bookingId} from Google Sheets (row ${rowIndex + 1})`);
        return true;
      } else {
        console.log(`⚠️ Booking ${bookingId} not found in Google Sheets for deletion`);
        return false;
      }
    } catch (error) {
      console.error('Error deleting booking from Google Sheets:', error);
      return false;
    }
  } 
}

server/services/paymentService.ts.content:
import { CashfreeService, CashfreeAPIError, PaymentRetryError } from './cashfreeService';
import { getPublicBaseUrlWithFallback } from '../utils/urlUtils';

export interface PaymentOrderData {
  bookingId: number;
  amount: number;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  baseUrl?: string; // Optional base URL for return/success URLs
}

export interface PaymentOrderResult {
  success: boolean;
  paymentLink?: string;
  orderId?: string;
  error?: string;
  userMessage?: string;
}

export interface PaymentVerificationResult {
  success: boolean;
  status?: string;
  amount?: number;
  paymentId?: string;
  error?: string;
  userMessage?: string;
}

export interface RefundResult {
  success: boolean;
  refundId?: string;
  refundStatus?: string;
  refundAmount?: number;
  error?: string;
  userMessage?: string;
}

export class PaymentService {
  private cashfree: CashfreeService;

  constructor() {
    this.cashfree = new CashfreeService();
  }

  async createPaymentOrder(bookingData: PaymentOrderData): Promise<PaymentOrderResult> {
    const orderId = this.cashfree.generateOrderId(bookingData.bookingId);

    try {
      console.log(`💳 Creating payment order for booking ${bookingData.bookingId} with amount ₹${bookingData.amount}`);

      // Validate input data
      this.validatePaymentOrderData(bookingData);

      const orderResponse = await this.cashfree.createOrder({
        order_amount: bookingData.amount,
        order_currency: 'INR',
        order_id: orderId,
        customer_details: {
          customer_id: `customer_${bookingData.bookingId}`,
          customer_name: bookingData.customerName,
          customer_email: bookingData.customerEmail,
          customer_phone: bookingData.customerPhone,
        },
        order_meta: {
          return_url: `${bookingData.baseUrl || getPublicBaseUrlWithFallback()}/payment/success?booking=${bookingData.bookingId}`,
          notify_url: this.getWebhookUrl(),
        },
      });

      console.log(`✅ Payment order created successfully: ${orderResponse.cf_order_id}`);

      return {
        success: true,
        paymentLink: orderResponse.payment_link,
        orderId: orderResponse.cf_order_id,
      };

    } catch (error: any) {
      console.error(`❌ Payment order creation failed for booking ${bookingData.bookingId}:`, error);

      const userMessage = this.cashfree.getUserFriendlyError(error);

      return {
        success: false,
        error: error.message,
        userMessage,
      };
    }
  }

  async verifyPayment(orderId: string): Promise<PaymentVerificationResult> {
    try {
      console.log(`🔍 Verifying payment for order: ${orderId}`);

      if (!orderId?.trim()) {
        throw new Error('Order ID is required for payment verification');
      }

      const orderStatus = await this.cashfree.getOrderStatus(orderId);

      console.log(`📊 Payment verification result for ${orderId}: ${orderStatus.order_status}`);

      return {
        success: true,
        status: orderStatus.order_status,
        amount: orderStatus.order_amount,
        paymentId: orderStatus.cf_order_id,
      };

    } catch (error: any) {
      console.error(`❌ Payment verification failed for order ${orderId}:`, error);

      const userMessage = this.cashfree.getUserFriendlyError(error);

      return {
        success: false,
        error: error.message,
        userMessage,
      };
    }
  }

  async processRefund(orderId: string, refundAmount: number, refundNote?: string): Promise<RefundResult> {
    try {
      console.log(`💰 Processing refund for order ${orderId}, amount: ₹${refundAmount}`);

      if (!orderId?.trim()) {
        throw new Error('Order ID is required for refund processing');
      }

      if (!refundAmount || refundAmount <= 0) {
        throw new Error('Valid refund amount is required');
      }

      const refundRequest = {
        refund_amount: refundAmount,
        refund_id: this.cashfree.generateRefundId(orderId),
        refund_note: refundNote || `Refund for order ${orderId}`
      };

      const refundResponse = await this.cashfree.createRefund(orderId, refundRequest);

      console.log(`✅ Refund processed successfully: ${refundResponse.cf_refund_id}`);

      return {
        success: true,
        refundId: refundResponse.cf_refund_id,
        refundStatus: refundResponse.refund_status,
        refundAmount: refundResponse.refund_amount,
      };

    } catch (error: any) {
      console.error(`❌ Refund processing failed for order ${orderId}:`, error);

      const userMessage = this.cashfree.getUserFriendlyError(error);

      return {
        success: false,
        error: error.message,
        userMessage,
      };
    }
  }

  async getRefundStatus(orderId: string, refundId: string): Promise<RefundResult> {
    try {
      console.log(`🔍 Checking refund status for order ${orderId}, refund ${refundId}`);

      const refundStatus = await this.cashfree.getRefundStatus(orderId, refundId);

      return {
        success: true,
        refundId: refundStatus.cf_refund_id,
        refundStatus: refundStatus.refund_status,
        refundAmount: refundStatus.refund_amount,
      };

    } catch (error: any) {
      console.error(`❌ Refund status check failed:`, error);

      const userMessage = this.cashfree.getUserFriendlyError(error);

      return {
        success: false,
        error: error.message,
        userMessage,
      };
    }
  }

  async calculateAmount(ticketCount: number, ticketPrice: number, couponDiscount: number = 0): Promise<number> {
    return await this.cashfree.calculateAmount(ticketCount, ticketPrice, couponDiscount);
  }

  async healthCheck(): Promise<boolean> {
    try {
      const isHealthy = await this.cashfree.healthCheck();
      console.log(`🏥 Payment service health check: ${isHealthy ? 'healthy' : 'unhealthy'}`);
      return isHealthy;
    } catch (error) {
      console.error('Payment service health check failed:', error);
      return false;
    }
  }

  private validatePaymentOrderData(data: PaymentOrderData): void {
    const errors: string[] = [];

    if (!data.bookingId || data.bookingId <= 0) {
      errors.push('Valid booking ID is required');
    }

    if (!data.amount || data.amount <= 0) {
      errors.push('Valid payment amount is required');
    }

    if (!data.customerName?.trim()) {
      errors.push('Customer name is required');
    }

    if (!data.customerEmail?.trim() || !this.isValidEmail(data.customerEmail)) {
      errors.push('Valid customer email is required');
    }

    if (!data.customerPhone?.trim() || !this.isValidPhone(data.customerPhone)) {
      errors.push('Valid customer phone number is required');
    }

    if (errors.length > 0) {
      throw new Error(`Invalid payment data: ${errors.join(', ')}`);
    }
  }

  private isValidEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  private isValidPhone(phone: string): boolean {
    // Accept any 10-digit phone number for flexibility
    const phoneRegex = /^\d{10}$/;
    return phoneRegex.test(phone.replace(/\D/g, ''));
  }

  /**
   * Centralized status mapping logic for consistent payment status handling
   * @param cashfreeStatus - The status from Cashfree API
   * @returns Internal payment status
   */
  mapCashfreeStatusToInternal(cashfreeStatus: string): 'pending' | 'verified' | 'failed' {
    const status = cashfreeStatus?.toUpperCase();

    // Definitive success states - only these should be mapped to 'verified'
    if (status === 'PAID' || status === 'SUCCESS') {
      return 'verified';
    }

    // Definitive failure states
    if (status === 'FAILED' || status === 'CANCELLED' || status === 'EXPIRED' || 
        status === 'TERMINATED' || status === 'USER_DROPPED') {
      return 'failed';
    }

    // In-progress or pending states - keep as pending
    // ACTIVE means payment link is open, NOT that payment is complete
    // CREATED, PENDING mean payment is not yet completed
    if (status === 'ACTIVE' || status === 'CREATED' || status === 'PENDING' || 
        status === 'INITIATED') {
      return 'pending';
    }

    // Unknown status - default to pending for safety
    console.warn(`⚠️ Unknown Cashfree status: ${status}. Defaulting to 'pending' for safety.`);
    return 'pending';
  }

  /**
   * Verify payment with proper status mapping
   * @param orderId - Cashfree order ID
   * @returns Payment verification result with mapped status
   */
  async verifyPaymentWithMapping(orderId: string): Promise<PaymentVerificationResult & { mappedStatus: string }> {
    try {
      console.log(`🔍 Verifying payment with status mapping for order: ${orderId}`);

      if (!orderId?.trim()) {
        throw new Error('Order ID is required for payment verification');
      }

      const orderStatus = await this.cashfree.getOrderStatus(orderId);
      const mappedStatus = this.mapCashfreeStatusToInternal(orderStatus.order_status);

      console.log(`📊 Payment verification for ${orderId}: ${orderStatus.order_status} -> ${mappedStatus}`);

      return {
        success: true,
        status: orderStatus.order_status,
        mappedStatus,
        amount: orderStatus.order_amount,
        paymentId: orderStatus.cf_order_id,
      };

    } catch (error: any) {
      console.error(`❌ Payment verification failed for order ${orderId}:`, error);

      const userMessage = this.cashfree.getUserFriendlyError(error);

      return {
        success: false,
        mappedStatus: 'pending', // Safe default
        error: error.message,
        userMessage,
      };
    }
  }

  private getWebhookUrl(): string {
    // Priority 1: Use REPLIT_DEV_DOMAIN for automatic Replit domain detection
    if (process.env.REPLIT_DEV_DOMAIN) {
      const webhookUrl = `https://${process.env.REPLIT_DEV_DOMAIN}/api/webhooks/cashfree`;
      console.log(`🌐 Using Replit public domain for webhook: ${webhookUrl}`);
      return webhookUrl;
    }

    // Priority 2: Use SERVER_URL if explicitly set
    if (process.env.SERVER_URL) {
      const baseUrl = process.env.SERVER_URL.endsWith('/') 
        ? process.env.SERVER_URL.slice(0, -1) 
        : process.env.SERVER_URL;
      const webhookUrl = `${baseUrl}/api/webhooks/cashfree`;
      console.log(`🔗 Using SERVER_URL for webhook: ${webhookUrl}`);
      return webhookUrl;
    }

    // Priority 3: Use APP_BASE_URL if set (alternative environment variable)
    if (process.env.APP_BASE_URL) {
      const baseUrl = process.env.APP_BASE_URL.endsWith('/') 
        ? process.env.APP_BASE_URL.slice(0, -1) 
        : process.env.APP_BASE_URL;
      const webhookUrl = `${baseUrl}/api/webhooks/cashfree`;
      console.log(`🔗 Using APP_BASE_URL for webhook: ${webhookUrl}`);
      return webhookUrl;
    }

    // Priority 4: For development, use HTTPS localhost since Cashfree requires HTTPS
    if (process.env.NODE_ENV === 'development') {
      // Use HTTPS by default for Cashfree compatibility, allow HTTP override for testing
      const forceHttps = process.env.FORCE_HTTPS_LOCALHOST !== 'false'; // Default to true
      const protocol = forceHttps ? 'https' : 'http';

      if (protocol === 'https') {
        console.warn('⚠️ Using HTTPS localhost webhook URL for Cashfree compatibility.');
        console.warn('💡 If you need HTTP for local testing, set FORCE_HTTPS_LOCALHOST=false');
        console.warn('💡 For production webhooks, use SERVER_URL or APP_BASE_URL environment variables');
      } else {
        console.warn('⚠️ Using HTTP localhost webhook URL. This will not work with Cashfree in production mode!');
      }

      const webhookUrl = `${protocol}://localhost:5000/api/webhooks/cashfree`;
      console.warn(`🚨 Using localhost webhook URL: ${webhookUrl} - This will NOT work with external services!`);
      return webhookUrl;
    }

    // Priority 5: Fallback to production URL (same as frontend base)
    const fallbackUrl = process.env.FRONTEND_URL || 'https://events.qlora.in';
    console.warn(`⚠️ No SERVER_URL, APP_BASE_URL, or REPLIT_DEV_DOMAIN configured. Using fallback: ${fallbackUrl}`);
    console.warn('💡 For production, set SERVER_URL environment variable to your publicly accessible backend URL');

    const baseUrl = fallbackUrl.endsWith('/') 
      ? fallbackUrl.slice(0, -1) 
      : fallbackUrl;
    const webhookUrl = `${baseUrl}/api/webhooks/cashfree`;
    console.warn(`🔗 Using fallback webhook URL: ${webhookUrl}`);
    return webhookUrl;
  }
}

