import { createHash, createHmac } from 'crypto';

// Custom error types for better error handling
export class CashfreeAPIError extends Error {
  constructor(
    message: string,
    public statusCode: number,
    public errorCode?: string,
    public details?: any
  ) {
    super(message);
    this.name = 'CashfreeAPIError';
  }
}

export class PaymentRetryError extends Error {
  constructor(message: string, public attempts: number) {
    super(message);
    this.name = 'PaymentRetryError';
  }
}

export interface CashfreePaymentRequest {
  order_amount: number;
  order_currency: string;
  order_id: string;
  customer_details: {
    customer_id: string;
    customer_name: string;
    customer_email: string;
    customer_phone: string;
  };
  order_meta?: {
    return_url?: string;
    notify_url?: string;
  };
}

export interface CashfreeOrderResponse {
  cf_order_id: string;
  order_id: string;
  payment_link: string;
  order_status: string;
  order_amount: number;
  order_currency: string;
}

export interface CashfreeRefundRequest {
  refund_amount: number;
  refund_id: string;
  refund_note?: string;
}

export interface CashfreeRefundResponse {
  cf_payment_id: string;
  cf_refund_id: string;
  refund_id: string;
  order_id: string;
  refund_amount: number;
  refund_status: string;
  refund_note?: string;
}

export class CashfreeService {
  private appId: string;
  private secretKey: string;
  private webhookSecret: string;
  private baseUrl: string;
  private maxRetries: number = 3;
  private retryDelay: number = 1000;
  private timeout: number = 30000;

  constructor() {
    // In development, use test credentials if environment variables are not set
    const isDevelopment = process.env.NODE_ENV === 'development';

    this.appId = process.env.CASHFREE_APP_ID || (isDevelopment ? 'TEST_DEVELOPMENT_APP_ID' : undefined);
    this.secretKey = process.env.CASHFREE_SECRET_KEY || (isDevelopment ? 'TEST_DEVELOPMENT_SECRET_KEY' : undefined);
    this.webhookSecret = process.env.CASHFREE_WEBHOOK_SECRET || (isDevelopment ? 'TEST_DEVELOPMENT_WEBHOOK_SECRET' : undefined);

    if (!this.appId || !this.secretKey || !this.webhookSecret) {
      throw new Error('Required Cashfree credentials not found in environment variables: CASHFREE_APP_ID, CASHFREE_SECRET_KEY, CASHFREE_WEBHOOK_SECRET');
    }

    if (isDevelopment && this.appId.startsWith('TEST_DEVELOPMENT')) {
      console.warn('⚠️  Using development test credentials for Cashfree. Set environment variables for production.');
    }

    // Determine environment based on app ID
    const isProduction = !this.appId.startsWith('TEST');
    this.baseUrl = isProduction ? 'https://api.cashfree.com/pg' : 'https://sandbox.cashfree.com/pg';

    console.log(`🔑 Cashfree Service initialized successfully`);
    console.log(`   Environment: ${isProduction ? 'Production' : 'Sandbox'}`);
    console.log(`   Base URL: ${this.baseUrl}`);
  }

  private generateSignature(data: string): string {
    return createHmac('sha256', this.secretKey).update(data).digest('base64');
  }

  private async makeRequest(
    url: string,
    method: 'GET' | 'POST',
    headers: Record<string, string>,
    body?: string
  ): Promise<any> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.timeout);

    try {
      const response = await fetch(url, {
        method,
        headers,
        body,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        const errorText = await response.text();
        let errorDetails;
        try {
          errorDetails = JSON.parse(errorText);
        } catch {
          errorDetails = { message: errorText };
        }

        console.error(`❌ Cashfree API Error (${response.status}):`, {
          url,
          method,
          status: response.status,
          errorText,
          errorDetails
        });

        throw new CashfreeAPIError(
          errorDetails.message || `API request failed with status ${response.status}`,
          response.status,
          errorDetails.error_code,
          errorDetails
        );
      }

      return await response.json();
    } catch (error: any) {
      clearTimeout(timeoutId);

      if (error.name === 'AbortError') {
        throw new CashfreeAPIError('Request timeout', 408);
      }

      if (error instanceof CashfreeAPIError) {
        throw error;
      }

      throw new CashfreeAPIError(
        'Network error occurred',
        0,
        'NETWORK_ERROR',
        { originalError: error.message }
      );
    }
  }

  private async retryRequest<T>(
    operation: () => Promise<T>,
    retryableErrors: number[] = [429, 500, 502, 503, 504]
  ): Promise<T> {
    let lastError: any;

    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      try {
        return await operation();
      } catch (error: any) {
        lastError = error;

        if (error instanceof CashfreeAPIError && retryableErrors.includes(error.statusCode)) {
          if (attempt < this.maxRetries) {
            console.log(`Retrying request (attempt ${attempt}/${this.maxRetries}) after error:`, error.message);
            await new Promise(resolve => setTimeout(resolve, this.retryDelay * attempt));
            continue;
          }
        }

        break;
      }
    }

    throw new PaymentRetryError(
      `Failed after ${this.maxRetries} attempts: ${lastError.message}`,
      this.maxRetries
    );
  }

  async createOrder(paymentData: CashfreePaymentRequest): Promise<CashfreeOrderResponse> {
    return this.retryRequest(async () => {
      const headers = {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'x-api-version': '2023-08-01',
        'x-client-id': this.appId,
        'x-client-secret': this.secretKey,
        'x-idempotency-key': paymentData.order_id,
      };

      console.log(`Creating Cashfree order for booking ${paymentData.order_id} with amount ₹${paymentData.order_amount}`);

      const result = await this.makeRequest(
        `${this.baseUrl}/orders`,
        'POST',
        headers,
        JSON.stringify(paymentData)
      );

      console.log(`✅ Cashfree order created successfully: ${result.cf_order_id}`);

      // Return payment session ID for SDK integration
      return {
        ...result,
        payment_link: result.payment_session_id // Use session ID for SDK
      };
    });
  }

  async getOrderStatus(orderId: string): Promise<any> {
    return this.retryRequest(async () => {
      const headers = {
        'Accept': 'application/json',
        'x-api-version': '2023-08-01',
        'x-client-id': this.appId,
        'x-client-secret': this.secretKey,
      };

      console.log(`🔍 Checking order status for: ${orderId}`);
      console.log(`🔗 API URL: ${this.baseUrl}/orders/${orderId}`);
      console.log(`🔑 Using App ID: ${this.appId.substring(0, 8)}...`);

      const result = await this.makeRequest(
        `${this.baseUrl}/orders/${orderId}`,
        'GET',
        headers
      );

      console.log(`📊 Order status for ${orderId}: ${result.order_status}`);
      return result;
    });
  }

  async verifyWebhook(signature: string, timestamp: string, rawBody: string): Promise<boolean> {
    try {
      if (!signature || !timestamp || !rawBody) {
        console.error('Missing webhook verification parameters');
        return false;
      }

      const signatureData = timestamp + rawBody;
      const expectedSignature = createHmac('sha256', this.webhookSecret).update(signatureData).digest('base64');

      const isValid = signature === expectedSignature;

      if (!isValid) {
        console.error('Webhook signature verification failed', {
          receivedSignature: signature,
          expectedSignature,
          timestamp,
          bodyLength: rawBody.length
        });
      } else {
        console.log('✅ Webhook signature verified successfully');
      }

      return isValid;
    } catch (error) {
      console.error('Error verifying webhook:', error);
      return false;
    }
  }

  generateOrderId(bookingId: number): string {
    const timestamp = Date.now();
    return `ORDER_${bookingId}_${timestamp}`;
  }

  generateRefundId(orderId: string): string {
    const timestamp = Date.now();
    return `REFUND_${orderId}_${timestamp}`;
  }

  async createRefund(orderId: string, refundData: CashfreeRefundRequest): Promise<CashfreeRefundResponse> {
    return this.retryRequest(async () => {
      const timestamp = Math.floor(Date.now() / 1000).toString();
      const signatureData = `POST\n/pg/orders/${orderId}/refunds\n${timestamp}`;
      const signature = this.generateSignature(signatureData);

      const headers = {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'x-api-version': '2023-08-01',
        'x-client-id': this.appId,
        'x-client-secret': this.secretKey,
        'x-idempotency-key': refundData.refund_id,
      };

      console.log(`Creating refund for order ${orderId} with amount ₹${refundData.refund_amount}`);

      const result = await this.makeRequest(
        `${this.baseUrl}/orders/${orderId}/refunds`,
        'POST',
        headers,
        JSON.stringify(refundData)
      );

      console.log(`✅ Refund created successfully: ${result.cf_refund_id}`);
      return result;
    });
  }

  async getRefundStatus(orderId: string, refundId: string): Promise<any> {
    return this.retryRequest(async () => {
      const timestamp = Math.floor(Date.now() / 1000).toString();
      const signatureData = `GET\n/pg/orders/${orderId}/refunds/${refundId}\n${timestamp}`;
      const signature = this.generateSignature(signatureData);

      const headers = {
        'Accept': 'application/json',
        'x-api-version': '2023-08-01',
        'x-client-id': this.appId,
        'x-client-secret': this.secretKey,
      };

      console.log(`Checking refund status for order ${orderId}, refund ${refundId}`);

      const result = await this.makeRequest(
        `${this.baseUrl}/orders/${orderId}/refunds/${refundId}`,
        'GET',
        headers
      );

      console.log(`📊 Refund status for ${refundId}: ${result.refund_status}`);
      return result;
    });
  }

  // Helper method to get user-friendly error messages
  getUserFriendlyError(error: any): string {
    if (error instanceof CashfreeAPIError) {
      switch (error.statusCode) {
        case 400:
          return 'Invalid payment information provided. Please check your details and try again.';
        case 401:
          return 'Cashfree authentication failed. API credentials may be invalid or expired. Please contact support.';
        case 403:
          return 'Payment not authorized. Please contact support.';
        case 404:
          return 'Payment order not found. This may be a very old order or the order ID might be incorrect.';
        case 408:
          return 'Payment request timed out. Please try again.';
        case 429:
          return 'Too many payment requests. Please wait a moment and try again.';
        case 500:
        case 502:
        case 503:
        case 504:
          return 'Payment service is temporarily unavailable. Please try again in a few minutes.';
        default:
          if (error.details?.message?.includes('authentication Failed')) {
            return 'Cashfree API authentication failed. Please contact support to update payment credentials.';
          }
          return error.details?.message || 'Payment processing failed. Please try again or contact support.';
      }
    }

    if (error instanceof PaymentRetryError) {
      return 'Cashfree API is currently unavailable after multiple attempts. Please try again later or contact support.';
    }

    return 'An unexpected error occurred during payment processing. Please contact support.';
  }

  async calculateAmount(ticketCount: number, ticketPrice: number, couponDiscount: number = 0): Promise<number> {
    let subtotal = ticketCount * ticketPrice;

    // Apply coupon discount to subtotal only (not to convenience fee)
    const discountAmount = (subtotal * couponDiscount) / 100;
    const subtotalAfterDiscount = subtotal - discountAmount;

    // Get convenience fee from configuration
    const { storage } = await import('../databaseStorage');
    const config = await storage.getTicketConfig();
    const convenienceFeePerTicket = parseFloat(config.convenientFee || '0');
    const convenienceFeeTotal = ticketCount * convenienceFeePerTicket;

    const totalAmount = subtotalAfterDiscount + convenienceFeeTotal;

    return Math.round(totalAmount * 100) / 100; // Round to 2 decimal places
  }

  // Enhanced payment status monitoring for webhook failures
  async monitorPaymentStatus(orderId: string, maxAttempts: number = 10): Promise<any> {
    console.log(`🔍 Starting payment monitoring for order ${orderId}`);

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        const status = await this.getOrderStatus(orderId);

        if (status.order_status === 'PAID' || status.order_status === 'FAILED') {
          console.log(`✅ Payment monitoring complete for ${orderId}: ${status.order_status}`);
          return status;
        }

        console.log(`🔄 Payment monitoring attempt ${attempt}/${maxAttempts} for ${orderId}: ${status.order_status}`);

        if (attempt < maxAttempts) {
          await new Promise(resolve => setTimeout(resolve, 30000)); // Wait 30 seconds
        }
      } catch (error: any) {
        console.error(`❌ Payment monitoring error for ${orderId} (attempt ${attempt}):`, error.message);

        if (attempt < maxAttempts) {
          await new Promise(resolve => setTimeout(resolve, 10000)); // Wait 10 seconds on error
        }
      }
    }

    throw new Error(`Payment monitoring timeout for order ${orderId} after ${maxAttempts} attempts`);
  }

  // Health check method to verify service connectivity
  async healthCheck(): Promise<boolean> {
    try {
      // Test connectivity with a minimal API call
      const timestamp = Math.floor(Date.now() / 1000).toString();
      const signatureData = `GET\n/pg/orders\n${timestamp}`;
      const signature = this.generateSignature(signatureData);

      const headers = {
        'Accept': 'application/json',
        'x-api-version': '2023-08-01',
        'x-client-id': this.appId,
        'x-client-secret': this.secretKey,
      };

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000); // 5 second timeout for health check

      const response = await fetch(`${this.baseUrl}/orders?limit=1`, {
        method: 'GET',
        headers,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      // 200 or 400 (bad request) both indicate the service is responsive
      return response.status === 200 || response.status === 400;
    } catch (error) {
      console.error('Cashfree health check failed:', error);
      return false;
    }
  }
}

