import React, { useEffect, useState } from 'react';
import { useParams } from 'wouter';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { useQuery } from '@tanstack/react-query';
import { Users, LogOut, RefreshCw, Share2, Copy, ExternalLink } from 'lucide-react';
import { format } from 'date-fns';
import { useToast } from '@/hooks/use-toast';

interface PromoterStats {
  totalBookings: number;
  totalTickets: number;
  promoterInfo: {
    name: string;
    email: string;
    promoCode: string;
    isActive: boolean;
    createdAt: string;
    lastLoginAt: string;
  };
  referralUrl: string;
  bookings: {
    id: number;
    name: string;
    email: string;
    phone: string;
    ticketCount: number;
    totalAmount: string;
    paymentStatus: string;
    createdAt: string;
  }[];
}

export default function PromoterDashboard() {
  const { promoCode } = useParams<{ promoCode: string }>();
  const [promoterSession, setPromoterSession] = useState<any>(null);
  const { toast } = useToast();

  useEffect(() => {
    const session = localStorage.getItem('promoterSession');
    if (session) {
      setPromoterSession(JSON.parse(session));
    } else {
      // Redirect to login if no session
      window.location.href = '/promoter/login';
    }
  }, []);

  const { data: stats, isLoading, error, refetch } = useQuery({
    queryKey: ['/api/promoter/dashboard', promoCode],
    queryFn: async () => {
      const response = await fetch(`/api/promoter/dashboard/${promoCode}`);
      if (!response.ok) {
        throw new Error('Failed to fetch dashboard data');
      }
      return response.json();
    },
    enabled: !!promoCode && !!promoterSession,
    retry: 1,
  });

  const handleLogout = () => {
    localStorage.removeItem('promoterSession');
    window.location.href = '/promoter/login';
  };

  const copyReferralUrl = async () => {
    const url = stats?.stats?.referralUrl || `https://telugunight.manipal.app/book?ref=${promoterSession?.promoCode}`;
    try {
      await navigator.clipboard.writeText(url);
      toast({
        title: "Copied to clipboard!",
        description: "Your referral URL has been copied.",
      });
    } catch (error) {
      toast({
        title: "Copy failed",
        description: "Please copy the URL manually.",
        variant: "destructive",
      });
    }
  };

  const shareOnSocial = (platform: string) => {
    const url = stats?.stats?.referralUrl || `https://telugunight.manipal.app/book?ref=${promoterSession?.promoCode}`;
    const text = 'Join me at Telugu Night! Book your tickets now!';

    let shareUrl = '';
    switch (platform) {
      case 'whatsapp':
        shareUrl = `https://wa.me/?text=${encodeURIComponent(`${text} ${url}`)}`;
        break;
      case 'facebook':
        shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`;
        break;
      case 'twitter':
        shareUrl = `https://twitter.com/intent/tweet?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}`;
        break;
      default:
        return;
    }

    window.open(shareUrl, '_blank', 'width=600,height=400');
  };

  const getPaymentStatusBadge = (status: string) => {
    const statusMap = {
      'pending': { variant: 'secondary' as const, text: 'Pending' },
      'verified': { variant: 'default' as const, text: 'Verified' },
      'failed': { variant: 'destructive' as const, text: 'Failed' },
    };
    const config = statusMap[status as keyof typeof statusMap] || statusMap.pending;
    return <Badge variant={config.variant}>{config.text}</Badge>;
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900">
        <div className="text-center">
          <RefreshCw className="animate-spin h-8 w-8 mx-auto mb-4" />
          <p>Loading your dashboard...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
