import { useEffect, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Card, CardContent } from '@/components/ui/card';
import { CheckCircle, Clock, XCircle, Loader2, Mail, AlertCircle } from 'lucide-react';

export default function PaymentSuccess() {
  const [bookingId, setBookingId] = useState<string | null>(null);
  const [countdown, setCountdown] = useState(30);

  // Extract booking ID from URL
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const booking = params.get('booking');
    if (booking) {
      setBookingId(booking);
    }
  }, []);

  // Fetch booking status from API
  const { data: bookingStatus, isLoading, error } = useQuery({
    queryKey: ['/api/bookings', bookingId, 'check-status'],
    queryFn: async () => {
      if (!bookingId) return null;
      const response = await fetch(`/api/bookings/${bookingId}/check-status`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });
      if (!response.ok) {
        throw new Error('Failed to fetch booking status');
      }
      return response.json();
    },
    enabled: !!bookingId,
    refetchInterval: 5000, // Refetch every 5 seconds
    retry: 3
  });

  // Auto-close countdown and page close
  useEffect(() => {
    const interval = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          // Close the tab/window after countdown reaches 0
          window.close();
          // If window.close() doesn't work (blocked by browser), redirect to home
          setTimeout(() => {
            window.location.href = '/';
          }, 500);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  // Get payment status from booking data
  const paymentStatus = bookingStatus?.status || bookingStatus?.paymentStatus;
  const isVerified = paymentStatus === 'verified' || paymentStatus === 'paid';
  const isFailed = paymentStatus === 'failed';
  const isPending = paymentStatus === 'pending';

  // Determine styling based on status
  const getStatusStyles = () => {
    if (isLoading || isPending) {
      return {
        background: 'from-blue-50 to-sky-100',
        cardBg: 'bg-blue-50',
        cardBorder: 'border-blue-200',
        iconColor: 'text-blue-500',
        titleColor: 'text-blue-600',
        badgeBg: 'bg-blue-100',
        badgeBorder: 'border-blue-300',
        badgeText: 'text-blue-800'
      };
    } else if (isFailed) {
      return {
        background: 'from-red-50 to-rose-100',
        cardBg: 'bg-red-50',
        cardBorder: 'border-red-200',
        iconColor: 'text-red-500',
        titleColor: 'text-red-600',
        badgeBg: 'bg-red-100',
        badgeBorder: 'border-red-300',
        badgeText: 'text-red-800'
      };
    } else {
      // Verified or default
      return {
        background: 'from-green-50 to-emerald-100',
        cardBg: 'bg-green-50',
        cardBorder: 'border-green-200',
        iconColor: 'text-green-500',
        titleColor: 'text-green-600',
        badgeBg: 'bg-green-100',
        badgeBorder: 'border-green-300',
        badgeText: 'text-green-800'
      };
    }
  };

  const styles = getStatusStyles();

  // Get appropriate icon
  const getStatusIcon = () => {
    if (isLoading) {
      return <Loader2 className={`h-20 w-20 ${styles.iconColor} mx-auto mb-6 animate-spin`} data-testid="icon-loading" />;
    } else if (isFailed) {
      return <XCircle className={`h-20 w-20 ${styles.iconColor} mx-auto mb-6`} data-testid="icon-failed" />;
    } else {
      return <CheckCircle className={`h-20 w-20 ${styles.iconColor} mx-auto mb-6`} data-testid="icon-success" />;
    }
  };

  // Get appropriate title and message
  const getStatusContent = () => {
    if (isLoading) {
      return {
        title: 'Checking Payment Status...',
        message: 'Please wait while we verify your payment.'
      };
    } else if (error) {
      return {
        title: 'Unable to Check Status',
        message: 'We could not verify your payment status. Please contact support if needed.'
      };
    } else if (isFailed) {
      return {
        title: 'Payment Rejected',
        message: 'Payment is rejected. We will send you a notification email shortly.'
      };
    } else if (isPending) {
      return {
        title: 'Payment Processing...',
        message: 'Your payment is being processed. We will update you shortly.'
      };
    } else {
      return {
        title: 'Payment Received! 🎉',
        message: 'Tickets will be sent to your mail shortly.'
      };
    }
  };

  const content = getStatusContent();

  // Get email alert content based on status
  const getEmailAlertContent = () => {
    if (isLoading) {
      return {
        message: "📧 We'll send updates to your email",
        subMessage: "Please keep checking your inbox for payment status updates",
        alertBg: "bg-blue-600",
        alertBorder: "border-blue-500",
        alertText: "text-white"
      };
    } else if (isFailed) {
      return {
        message: "📧 CHECK YOUR EMAIL!",
        subMessage: "Payment failed - we've sent you a detailed notification email",
        alertBg: "bg-red-600",
        alertBorder: "border-red-500",
        alertText: "text-white"
      };
    } else if (isPending) {
      return {
        message: "📧 CHECK YOUR EMAIL!",
        subMessage: "We'll send payment confirmation and tickets to your email shortly",
        alertBg: "bg-orange-600",
        alertBorder: "border-orange-500",
        alertText: "text-white"
      };
    } else {
      // Verified or success
      return {
        message: "📧 CHECK YOUR EMAIL!",
        subMessage: "Your tickets have been sent to your email address",
        alertBg: "bg-green-600",
        alertBorder: "border-green-500",
        alertText: "text-white"
      };
    }
  };

  const emailAlert = getEmailAlertContent();

  return (
    <div className={`min-h-screen bg-gradient-to-br ${styles.background} flex flex-col items-center justify-center px-4 py-8`} data-testid="page-payment-success">
      {/* Prominent Email Alert Box */}
      <div className={`w-full max-w-lg mb-6 ${emailAlert.alertBg} ${emailAlert.alertBorder} border-2 rounded-xl shadow-2xl transform hover:scale-105 transition-transform duration-200`} data-testid="alert-check-email">
        <div className="p-6 text-center">
          <div className="flex items-center justify-center mb-4">
            <Mail className={`h-12 w-12 ${emailAlert.alertText} animate-bounce`} />
            <AlertCircle className={`h-8 w-8 ${emailAlert.alertText} ml-2 animate-pulse`} />
          </div>
          <h2 className={`text-2xl font-bold ${emailAlert.alertText} mb-2 uppercase tracking-wide`} data-testid="text-email-alert-title">
            {emailAlert.message}
          </h2>
          <p className={`text-lg ${emailAlert.alertText} opacity-90`} data-testid="text-email-alert-message">
            {emailAlert.subMessage}
          </p>
        </div>
      </div>

      <Card className={`max-w-md w-full ${styles.cardBorder} ${styles.cardBg}`}>
        <CardContent className="text-center p-8">
          {getStatusIcon()}

          <h1 className={`text-3xl font-bold ${styles.titleColor} mb-4`} data-testid="text-status-title">
            {content.title}
          </h1>

          <p className="text-gray-700 text-lg mb-6" data-testid="text-status-message">
            {content.message}
          </p>

          {bookingId && (
            <div className={`mb-6 ${styles.badgeBg} ${styles.badgeBorder} border rounded-lg p-3 inline-block`}>
              <p className={`${styles.badgeText} font-medium`} data-testid="text-booking-id">
                Booking ID: #{bookingId}
              </p>
            </div>
          )}

          {error && (
            <div className="mb-6 bg-yellow-100 border border-yellow-300 rounded-lg p-3">
              <p className="text-yellow-800 text-sm" data-testid="text-error">
                Error: {error.message}
              </p>
            </div>
          )}

          <div className="flex items-center justify-center gap-2 text-gray-600">
            <Clock className="h-4 w-4" />
            <p className="text-sm" data-testid="text-countdown">
              This page will close in {countdown} seconds
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/PaymentFailure.tsx.content:
import { useEffect, useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { apiRequest } from '@/lib/queryClient';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { XCircle, AlertTriangle, RotateCcw, Home } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import type { Booking } from '../../../shared/schema';

export default function PaymentFailure() {
  const { toast } = useToast();
  const [bookingId, setBookingId] = useState<number | null>(null);
  const [isRedirecting, setIsRedirecting] = useState(false);
  const [redirectMessage, setRedirectMessage] = useState('');

  // Extract booking ID from URL with enhanced validation
  useEffect(() => {
    console.log('🔍 PaymentFailure: Extracting booking ID from URL:', window.location.search);
    const params = new URLSearchParams(window.location.search);
    const booking = params.get('booking');

    if (booking) {
      const parsedId = parseInt(booking);
      if (!isNaN(parsedId) && parsedId > 0) {
        console.log('✅ PaymentFailure: Valid booking ID extracted:', parsedId);
        setBookingId(parsedId);
      } else {
        console.error('❌ PaymentFailure: Invalid booking ID format:', booking);
      }
    } else {
      console.error('❌ PaymentFailure: No booking parameter found in URL');
    }
  }, []);

  // Fetch booking details with enhanced error handling
  const { data: booking, isLoading, error } = useQuery<Booking>({
    queryKey: [`/api/bookings/${bookingId}`],
    enabled: !!bookingId,
    retry: 1
  });

  // Add logging for booking data fetch
  useEffect(() => {
    if (error) {
      console.error('❌ PaymentFailure: Failed to fetch booking:', error);
    }
    if (booking) {
      console.log('✅ PaymentFailure: Booking data fetched:', booking.id, 'Status:', booking.paymentStatus);
    }
  }, [booking, error]);

  // Delete failed booking mutation
  const deleteBookingMutation = useMutation({
    mutationFn: async () => {
      return apiRequest('DELETE', `/api/public/bookings/${bookingId}/delete-failed`);
    },
    onSuccess: () => {
      toast({
        title: "Booking Cancelled",
        description: "Your failed booking has been removed. You can try booking again.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to cancel booking.",
        variant: "destructive",
      });
    },
  });

  const handleRetryPayment = () => {
    console.log('🔄 PaymentFailure: Starting retry payment process for booking:', bookingId);
    // Delete the failed booking and redirect to home for new booking
    deleteBookingMutation.mutate();
    setIsRedirecting(true);
    setRedirectMessage('Cancelling failed booking and redirecting to home...');
    setTimeout(() => {
      window.location.href = '/';
    }, 2000);
  };

  const handleHomeRedirect = () => {
    console.log('🏠 PaymentFailure: Redirecting to home page');
    setIsRedirecting(true);
    setRedirectMessage('Returning to home page...');
    setTimeout(() => {
      window.location.href = '/';
    }, 1000);
  };

  // Show redirecting state
  if (isRedirecting) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center px-4" data-testid="page-redirecting">
        <Card className="max-w-md w-full">
          <CardContent className="text-center p-6 sm:p-8">
            <RotateCcw className="h-12 w-12 sm:h-16 sm:w-16 text-blue-500 mx-auto mb-4 animate-spin" data-testid="spinner-redirect" />
            <h2 className="text-xl sm:text-2xl font-bold text-gray-800 mb-2" data-testid="text-redirect-title">Processing...</h2>
            <p className="text-gray-600 text-sm sm:text-base" data-testid="text-redirect-message">{redirectMessage}</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!bookingId) {
    console.error('❌ PaymentFailure: No booking ID provided');
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50 to-red-100 flex items-center justify-center px-4" data-testid="page-invalid-link">
        <Card className="max-w-md w-full">
          <CardContent className="text-center p-6 sm:p-8">
            <AlertTriangle className="h-12 w-12 sm:h-16 sm:w-16 text-red-500 mx-auto mb-4" data-testid="icon-error" />
            <h2 className="text-xl sm:text-2xl font-bold text-red-600 mb-2" data-testid="text-error-title">Invalid Payment Link</h2>
            <p className="text-gray-600 mb-6 text-sm sm:text-base" data-testid="text-error-description">The payment link is missing booking information.</p>
            <Button onClick={handleHomeRedirect} className="w-full sm:w-auto" data-testid="button-home">
              Return to Home
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (isLoading) {
    console.log('⏳ PaymentFailure: Loading booking data for ID:', bookingId);
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50 to-red-100 flex items-center justify-center px-4" data-testid="page-loading">
        <Card className="max-w-md w-full">
          <CardContent className="text-center p-6 sm:p-8">
            <AlertTriangle className="h-12 w-12 sm:h-16 sm:w-16 text-red-500 mx-auto mb-4 animate-pulse" data-testid="spinner-loading" />
            <h2 className="text-xl sm:text-2xl font-bold text-gray-800 mb-2" data-testid="text-loading-title">Loading Payment Details...</h2>
            <p className="text-gray-600 text-sm sm:text-base" data-testid="text-loading-description">Please wait while we fetch your payment information.</p>
            <p className="text-sm text-gray-500 mt-2" data-testid="text-booking-id">Booking ID: #{bookingId}</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error || !booking) {
    console.error('❌ PaymentFailure: Booking not found or error occurred:', error);
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50 to-red-100 flex items-center justify-center px-4" data-testid="page-error">
        <Card className="max-w-md w-full">
          <CardContent className="text-center p-6 sm:p-8">
            <XCircle className="h-12 w-12 sm:h-16 sm:w-16 text-red-500 mx-auto mb-4" data-testid="icon-error" />
            <h2 className="text-xl sm:text-2xl font-bold text-red-600 mb-2" data-testid="text-error-title">Booking Not Found</h2>
            <p className="text-gray-600 mb-6 text-sm sm:text-base" data-testid="text-error-description">We couldn't find your booking details. Please contact support.</p>
            <p className="text-sm text-gray-500 mb-4" data-testid="text-booking-id">Booking ID: #{bookingId}</p>
            <Button onClick={handleHomeRedirect} className="w-full sm:w-auto" data-testid="button-home">
              Return to Home
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-red-50 to-red-100">
      <div className="container mx-auto px-4 py-8">
        <div className="max-w-2xl mx-auto">
          {/* Failure Header */}
          <Card className="mb-6 border-red-200 bg-red-50" data-testid="card-failure-header">
            <CardContent className="text-center p-8">
              <XCircle className="h-20 w-20 text-red-500 mx-auto mb-4" data-testid="icon-failure" />
              <h1 className="text-3xl font-bold text-red-600 mb-2" data-testid="text-failure-title">
                Payment Failed ❌
              </h1>
              <p className="text-gray-700 text-lg" data-testid="text-failure-description">
                Unfortunately, your payment could not be processed.
              </p>
              {booking && (
                <div className="mt-4 bg-red-100 border border-red-300 rounded-lg p-3 inline-block" data-testid="container-booking-id">
                  <p className="text-red-800 font-medium" data-testid="text-booking-id">
                    Booking ID: #{booking.id}
                  </p>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Booking Details (if available) */}
          {booking && (
            <Card className="mb-6">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-red-600">
                  <AlertTriangle className="h-5 w-5" />
                  Failed Booking Details
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <p className="font-medium text-gray-600">Name</p>
                    <p className="text-lg">{booking.name}</p>
                  </div>
                  <div>
                    <p className="font-medium text-gray-600">Email</p>
                    <p className="text-lg">{booking.email}</p>
                  </div>
                  <div>
                    <p className="font-medium text-gray-600">Tickets</p>
                    <p className="text-lg">{booking.ticketCount}</p>
                  </div>
                  <div>
                    <p className="font-medium text-gray-600">Amount</p>
                    <p className="text-lg text-red-600 font-bold">₹{booking.totalAmount}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Failure Reasons */}
          <Card className="mb-6">
            <CardHeader>
              <CardTitle>Common Reasons for Payment Failure</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3 text-gray-700">
              <p>• <strong>Insufficient funds:</strong> Your account may not have enough balance</p>
              <p>• <strong>Network issues:</strong> Poor internet connection during payment</p>
              <p>• <strong>Bank restrictions:</strong> Your bank may have declined the transaction</p>
              <p>• <strong>Card issues:</strong> Expired card or incorrect details</p>
              <p>• <strong>Payment timeout:</strong> Transaction took too long to complete</p>
            </CardContent>
          </Card>

          {/* Action Options */}
          <Card className="mb-6">
            <CardHeader>
              <CardTitle>What would you like to do?</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <h4 className="font-medium text-blue-800 mb-2">Option 1: Try Booking Again</h4>
                <p className="text-sm text-gray-600 mb-3">
                  We'll cancel this failed booking and you can create a new one with the same details.
                </p>
                <Button 
                  onClick={handleRetryPayment}
                  disabled={deleteBookingMutation.isPending || isRedirecting}
                  className="bg-blue-600 hover:bg-blue-700"
                  data-testid="button-retry-payment"
                >
                  {deleteBookingMutation.isPending || isRedirecting ? (
                    <>
                      <RotateCcw className="h-4 w-4 mr-2 animate-spin" />
                      {isRedirecting ? 'Redirecting...' : 'Cancelling...'}
                    </>
                  ) : (
                    <>
                      <RotateCcw className="h-4 w-4 mr-2" />
                      Cancel & Try Again
                    </>
                  )}
                </Button>
              </div>

              <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                <h4 className="font-medium text-gray-800 mb-2">Option 2: Return to Home</h4>
                <p className="text-sm text-gray-600 mb-3">
                  Go back to the main page without making any changes.
                </p>
                <Button 
                  onClick={handleHomeRedirect}
                  variant="outline"
                  disabled={isRedirecting}
                  data-testid="button-home"
                >
                  <Home className="h-4 w-4 mr-2" />
                  Return to Home
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Support Information */}
          <Card>
            <CardHeader>
              <CardTitle>Need Help?</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3 text-sm text-gray-600">
              <p>📧 <strong>Email Support:</strong> mis@aashveetech.com</p>
              <p>📞 <strong>Phone Support:</strong> +91 6281614117</p>
              <p>💬 <strong>What to include:</strong> Your booking ID #{booking?.id} and payment details</p>
              <p>⏰ <strong>Response Time:</strong> We typically respond within 2-4 hours</p>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

client/src/components/CouponManagement.t.content:
import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { Plus, Trash2, Tag, Users, AlertCircle, Calendar } from "lucide-react";
import { format } from 'date-fns';

interface Coupon {
  id: number;
  code: string;
  discount: number;
  isActive: boolean;
  usageLimit: number | null;
  usageCount: number;
  validFrom: string | null;
  validTo: string | null;
  createdAt: string;
}

export default function CouponManagement() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [newCoupon, setNewCoupon] = useState({
    code: '',
    discount: 10,
    usageLimit: 50,
    validFrom: '',
    validTo: ''
  });

  // Fetch coupons
  const { data: coupons, isLoading } = useQuery({
    queryKey: ['/api/coupons'],
    retry: 1,
  });

  // Create coupon mutation
  const createCouponMutation = useMutation({
    mutationFn: async (couponData: any) => {
      return apiRequest('POST', '/api/coupons', couponData);
    },
    onSuccess: () => {
      toast({
        title: "Coupon created successfully",
        description: "New coupon is now available for use",
      });
      setNewCoupon({ code: '', discount: 10, usageLimit: 50, validFrom: '', validTo: '' });
      queryClient.invalidateQueries({ queryKey: ['/api/coupons'] });
    },
    onError: (error: Error) => {
      toast({
        title: "Failed to create coupon",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Toggle coupon status mutation
  const toggleCouponMutation = useMutation({
    mutationFn: async ({ id, isActive }: { id: number; isActive: boolean }) => {
      return apiRequest('PATCH', `/api/coupons/${id}`, { isActive });
    },
    onSuccess: () => {
      toast({
        title: "Coupon status updated",
        description: "Coupon status has been changed successfully",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/coupons'] });
    },
    onError: (error: Error) => {
      toast({
        title: "Failed to update coupon",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Delete coupon mutation
  const deleteCouponMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiRequest('DELETE', `/api/coupons/${id}`);
    },
    onSuccess: () => {
      toast({
        title: "Coupon deleted",
        description: "Coupon has been removed successfully",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/coupons'] });
    },
    onError: (error: Error) => {
      toast({
        title: "Failed to delete coupon",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleCreateCoupon = () => {
    if (!newCoupon.code || newCoupon.discount <= 0) {
      toast({
        title: "Invalid input",
        description: "Coupon code and discount are required",
        variant: "destructive",
      });
      return;
    }

    // Format the coupon data
    const couponData = {
      ...newCoupon,
      code: newCoupon.code.toUpperCase(),
      validFrom: newCoupon.validFrom ? new Date(newCoupon.validFrom).toISOString() : null,
      validTo: newCoupon.validTo ? new Date(newCoupon.validTo).toISOString() : null,
    };

    createCouponMutation.mutate(couponData);
  };

  const getCouponStatus = (coupon: Coupon) => {
    if (!coupon.isActive) return { text: "Inactive", variant: "secondary" as const, color: "text-gray-600" };

    const now = new Date();
    const validFrom = coupon.validFrom ? new Date(coupon.validFrom) : null;
    const validTo = coupon.validTo ? new Date(coupon.validTo) : null;

    if (validFrom && now < validFrom) {
      return { text: "Scheduled", variant: "outline" as const, color: "text-blue-600" };
    }

    if (validTo && now > validTo) {
      return { text: "Expired", variant: "destructive" as const, color: "text-red-600" };
    }

    if (coupon.usageLimit && coupon.usageCount >= coupon.usageLimit) {
      return { text: "Exhausted", variant: "destructive" as const, color: "text-red-600" };
    }

    return { text: "Active", variant: "default" as const, color: "text-green-600" };
  };

  if (isLoading) {
    return (
      <div className="flex justify-center p-8">
        <div className="animate-spin w-8 h-8 border-4 border-primary border-t-transparent rounded-full" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Create New Coupon */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Plus className="w-5 h-5" />
            Create New Coupon
          </CardTitle>
          <CardDescription>
            Add promotional coupons with usage limits and validity periods
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
            <div className="space-y-2">
              <Label htmlFor="coupon-code">Coupon Code</Label>
              <Input
                id="coupon-code"
                placeholder="SAVE20"
                value={newCoupon.code}
                onChange={(e) => setNewCoupon({ ...newCoupon, code: e.target.value.toUpperCase() })}
                data-testid="input-coupon-code"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="discount">Discount (%)</Label>
              <Input
                id="discount"
                type="number"
                min="1"
                max="100"
                placeholder="10"
                value={newCoupon.discount}
                onChange={(e) => setNewCoupon({ ...newCoupon, discount: parseInt(e.target.value) || 0 })}
                data-testid="input-discount"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="usage-limit">Usage Limit</Label>
              <Input
                id="usage-limit"
                type="number"
                min="1"
                placeholder="50"
                value={newCoupon.usageLimit}
                onChange={(e) => setNewCoupon({ ...newCoupon, usageLimit: parseInt(e.target.value) || 0 })}
                data-testid="input-usage-limit"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="valid-from">Valid From</Label>
              <Input
                id="valid-from"
                type="datetime-local"
                value={newCoupon.validFrom}
                onChange={(e) => setNewCoupon({ ...newCoupon, validFrom: e.target.value })}
                data-testid="input-valid-from"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="valid-to">Valid To</Label>
              <Input
                id="valid-to"
                type="datetime-local"
                value={newCoupon.validTo}
                onChange={(e) => setNewCoupon({ ...newCoupon, validTo: e.target.value })}
                data-testid="input-valid-to"
              />
            </div>
          </div>

          <Button 
            onClick={handleCreateCoupon}
            disabled={createCouponMutation.isPending}
            className="w-full md:w-auto"
            data-testid="button-create-coupon"
          >
            {createCouponMutation.isPending ? (
              <div className="animate-spin w-4 h-4 border-2 border-current border-t-transparent rounded-full mr-2" />
            ) : (
              <Tag className="w-4 h-4 mr-2" />
            )}
            {createCouponMutation.isPending ? "Creating..." : "Create Coupon"}
          </Button>
        </CardContent>
      </Card>

      {/* Coupons List */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Tag className="w-5 h-5" />
            Coupon Management
          </CardTitle>
          <CardDescription>
            View and manage all promotional coupons
          </CardDescription>
        </CardHeader>
        <CardContent>
          {(coupons as any)?.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Coupon Details</TableHead>
                  <TableHead>Discount</TableHead>
                  <TableHead>Usage</TableHead>
                  <TableHead>Validity</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {((coupons as any) || []).map((coupon: Coupon, index: number) => {
                  const status = getCouponStatus(coupon);
                  return (
                    <TableRow key={coupon.id} data-testid={`row-coupon-${index}`}>
                      <TableCell>
                        <div>
                          <p className="font-medium font-mono">{coupon.code}</p>
                          <p className="text-xs text-gray-400">
                            Created {format(new Date(coupon.createdAt), 'MMM dd, yyyy')}
                          </p>
                        </div>
                      </TableCell>

                      <TableCell>
                        <Badge variant="outline" className="font-semibold">
                          {coupon.discount}% OFF
                        </Badge>
                      </TableCell>

                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Users className="w-4 h-4 text-blue-500" />
                          <span>{coupon.usageCount}</span>
                          {coupon.usageLimit && (
                            <span className="text-gray-500">/ {coupon.usageLimit}</span>
                          )}
                        </div>
                        {coupon.usageLimit && (
                          <div className="w-full bg-gray-200 rounded-full h-1.5 mt-1">
                            <div 
                              className="bg-blue-600 h-1.5 rounded-full" 
                              style={{ width: `${Math.min((coupon.usageCount / coupon.usageLimit) * 100, 100)}%` }}
                            />
                          </div>
                        )}
                      </TableCell>

                      <TableCell>
                        <div className="text-sm">
                          {coupon.validFrom && (
                            <p className="text-gray-600">
                              From: {format(new Date(coupon.validFrom), 'MMM dd, yyyy')}
                            </p>
                          )}
                          {coupon.validTo && (
                            <p className="text-gray-600">
                              To: {format(new Date(coupon.validTo), 'MMM dd, yyyy')}
                            </p>
                          )}
                          {!coupon.validFrom && !coupon.validTo && (
                            <p className="text-gray-500">No expiry</p>
                          )}
                        </div>
                      </TableCell>

                      <TableCell>
                        <Badge variant={status.variant} className={status.color}>
                          {status.text}
                        </Badge>
                      </TableCell>

                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Button
                            size="sm"
                            variant={coupon.isActive ? "outline" : "default"}
                            onClick={() => toggleCouponMutation.mutate({ 
                              id: coupon.id, 
                              isActive: !coupon.isActive 
                            })}
                            disabled={toggleCouponMutation.isPending}
                            data-testid={`button-toggle-coupon-${index}`}
                          >
                            {coupon.isActive ? "Deactivate" : "Activate"}
                          </Button>
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => deleteCouponMutation.mutate(coupon.id)}
                            disabled={deleteCouponMutation.isPending}
                            data-testid={`button-delete-coupon-${index}`}
                          >
                            <Trash2 className="w-3 h-3" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          ) : (
            <div className="text-center py-8">
              <AlertCircle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-500">No coupons found</p>
              <p className="text-sm text-gray-400">Create your first promotional coupon to get started</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

